<?php
require_once __DIR__ . '/../config/config.php';
require_once __DIR__ . '/../includes/auth.php';
require_once __DIR__ . '/../includes/app_state.php';
require_once __DIR__ . '/../includes/gemini.php';
require_once __DIR__ . '/../includes/groq.php';
require_once __DIR__ . '/../includes/mistral.php';
if (empty($_SESSION['admin_logged_in']) || $_SESSION['admin_logged_in'] !== true || ($_SESSION['role'] ?? '') !== 'admin') {
 if ($_SERVER['REQUEST_METHOD']==='POST') { http_response_code(401); header('Content-Type: application/json'); echo json_encode(['success'=>false,'error'=>'Session administrateur requise.']); exit; }
 header('Location: /api/login.php?next=admin'); exit;
}
$defs=['gemini'=>['label'=>'Google Gemini','model'=>'gemini-2.5-flash','models'=>['gemini-2.5-flash','gemini-2.0-flash'],'key'=>'geminiApiKey'],'mistral'=>['label'=>'Mistral AI','model'=>'mistral-small-latest','models'=>['mistral-small-latest','mistral-large-latest'],'key'=>'mistralApiKey'],'groq'=>['label'=>'Groq','model'=>'llama-3.3-70b-versatile','models'=>['llama-3.3-70b-versatile','openai/gpt-oss-20b'],'key'=>'groqApiKey']];
$state=load_app_state(); if(!isset($state['scanVars'])||!is_array($state['scanVars']))$state['scanVars']=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 header('Content-Type: application/json; charset=utf-8'); $in=json_decode(file_get_contents('php://input'),true);
 if(!is_array($in)){http_response_code(400);echo json_encode(['success'=>false,'error'=>'JSON invalide']);exit;}
 $p=strtolower((string)($in['provider']??''));$action=$in['action']??'save';
 if($action==='default'){if(!isset($defs[$p])){http_response_code(400);echo json_encode(['success'=>false,'error'=>'Fournisseur invalide']);exit;}$state['scanVars']['aiProvider']=$p;if(!save_app_state($state)){http_response_code(500);echo json_encode(['success'=>false,'error'=>'Sauvegarde impossible']);exit;}echo json_encode(['success'=>true,'message'=>'Fournisseur principal enregistré.']);exit;}
 if(!isset($defs[$p])){http_response_code(400);echo json_encode(['success'=>false,'error'=>'Fournisseur invalide']);exit;}
 if($action==='test'){
  $key=trim((string)($state['scanVars'][$defs[$p]['key']]??''));if($key===''){http_response_code(400);echo json_encode(['success'=>false,'error'=>'Enregistrez d’abord une clé API.']);exit;}
  $model=$state['scanVars'][$p.'Model']??$defs[$p]['model'];
  if($p==='gemini')$reply=call_gemini($model,['contents'=>[['parts'=>[['text'=>'Réponds uniquement OK']]]],'generationConfig'=>['temperature'=>0]],$key);
  elseif($p==='mistral')$reply=call_mistral(['model'=>$model,'messages'=>[['role'=>'user','content'=>'Réponds uniquement OK']],'temperature'=>0],$key);
  else $reply=call_groq(['model'=>$model,'messages'=>[['role'=>'user','content'=>'Réponds uniquement OK']],'temperature'=>0],$key);
  $ok=is_string($reply)&&trim($reply)!==''&&stripos($reply,'Erreur')!==0&&stripos($reply,'HTTP ')===false;
  if(!$ok)error_log('GreenHumble provider test failed: '.$p.'; no key logged');
  if(!$ok)http_response_code(502);echo json_encode(['success'=>$ok,'message'=>$ok?'Connexion fournisseur réussie.':'Échec : vérifiez la clé, le modèle, les quotas et les journaux serveur.']);exit;
 }
 $model=trim((string)($in['model']??$defs[$p]['model']));if(!in_array($model,$defs[$p]['models'],true)){http_response_code(400);echo json_encode(['success'=>false,'error'=>'Modèle non autorisé']);exit;}
 $state['scanVars'][$p.'Model']=$model;$newKey=trim((string)($in['apiKey']??''));if($newKey!=='')$state['scanVars'][$defs[$p]['key']]=$newKey;
 if(!save_app_state($state)){http_response_code(500);echo json_encode(['success'=>false,'error'=>'Sauvegarde impossible']);exit;}
 echo json_encode(['success'=>true,'message'=>'Configuration sauvegardée. La clé ne sera pas renvoyée.','configured'=>!empty($state['scanVars'][$defs[$p]['key']])]);exit;
}
$state=load_app_state();$vars=$state['scanVars']??[];$active=$vars['aiProvider']??'gemini';
?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GreenHumble — Configuration IA</title>
