ground:var(--mint);color:var(--g)}.result{font-size:13px;margin-top:10px;min-height:20px}@media(max-width:900px){.shell{grid-template-columns:1fr}.side{padding:10px}.brand{margin:4px 8px 8px}.nav{display:inline-block;padding:8px}.main{padding:18px}.layout,.fields{grid-template-columns:1fr}.top{align-items:start;flex-direction:column}}
</style></head><body><div class="shell"><aside class="side"><div class="brand">◈ GreenHumble</div><a class="nav" href="/api/admin/index.php">Tableau de bord</a><a class="nav" href="/api/admin/index.php?tab=audits">Audits</a><a class="nav active" href="/api/admin/ai_providers.php">IA &amp; API</a><a class="nav" href="/api/admin/index.php?tab=team">Utilisateurs &amp; rôles</a></aside><main class="main"><div class="top"><div><div class="eyebrow">Configuration système</div><h1>Fournisseurs d’intelligence artificielle</h1><p>Configurez séparément les clés, modèles et fournisseur principal.</p></div><span class="badge">● Console administrateur</span></div><div class="layout"><section>
<?php foreach($defs as $p=>$d): $configured=!empty($vars[$d['key']]); ?><article class="card"><div class="head"><div><h2><?=htmlspecialchars($d['label'],ENT_QUOTES,'UTF-8')?></h2><p><?=htmlspecialchars($p==='gemini'?'Analyse Google':($p==='mistral'?'Modèles Mistral AI':'Inférence Groq'),ENT_QUOTES,'UTF-8')?></p></div><span class="status <?=$configured?'ok':''?>"><?=$configured?'Clé configurée':'À configurer'?></span></div><div class="fields"><div class="field"><label for="key-<?=$p?>">Clé API</label><input id="key-<?=$p?>" type="password" autocomplete="new-password" placeholder="<?=$configured?'Clé enregistrée — saisir pour remplacer':'Collez votre clé API'?>"><div class="hint">La clé enregistrée n’est jamais affichée.</div></div><div class="field"><label for="model-<?=$p?>">Modèle</label><select id="model-<?=$p?>"><?php foreach($d['models'] as $m): ?><option value="<?=htmlspecialchars($m,ENT_QUOTES,'UTF-8')?>" <?=($vars[$p.'Model']??$d['model'])===$m?'selected':''?>><?=htmlspecialchars($m,ENT_QUOTES,'UTF-8')?></option><?php endforeach; ?></select></div></div><div class="actions"><button class="btn primary" onclick="saveProvider('<?=$p?>')">Enregistrer</button><button class="btn secondary" onclick="testProvider('<?=$p?>')">Tester la connexion</button></div><div class="result" id="result-<?=$p?>" role="status"></div></article><?php endforeach; ?>
<article class="card"><h2>Fournisseur utilisé par défaut</h2><p>Ce fournisseur sera utilisé pour les nouveaux audits.</p><div class="field" style="margin-top:14px"><label for="active-provider">Fournisseur principal</label><select id="active-provider"><?php foreach($defs as $p=>$d): ?><option value="<?=$p?>" <?=$active===$p?'selected':''?>><?=htmlspecialchars($d['label'],ENT_QUOTES,'UTF-8')?></option><?php endforeach; ?></select></div><div class="actions"><button class="btn primary" onclick="saveDefault()">Enregistrer le fournisseur principal</button></div><div class="result" id="result-default"></div></article></section><aside><div class="panel"><h3>État des fournisseurs</h3><?php foreach($defs as $p=>$d): ?><p><strong><?=htmlspecialchars($d['label'],ENT_QUOTES,'UTF-8')?></strong><br><span class="status <?=!empty($vars[$d['key']])?'ok':''?>"><?=!empty($vars[$d['key']])?'Clé présente':'Clé absente'?></span></p><?php endforeach; ?></div><div class="panel"><h3>Sécurité</h3><p class="note">Les clés ne sont jamais renvoyées au navigateur après sauvegarde. Ne les partagez pas par e-mail.</p></div><div class="panel"><h3>À savoir</h3><p class="note">Un test réussi vérifie l’accès fournisseur, pas l’exactitude juridique d’un audit.</p></div></aside></div><p class="note">GreenHumble · Configuration enregistrée dans l’état applicatif serveur.</p></main></div>
<script>
async function api(payload){const r=await fetch('/api/admin/ai_providers.php',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(payload)});const d=await r.json();if(!r.ok||!d.success)throw new Error(d.error||d.message||'Erreur serveur');return d}
async function saveProvider(p){const el=document.getElementById('result-'+p);el.textContent='Enregistrement…';try{const d=await api({action:'save',provider:p,apiKey:document.getElementById('key-'+p).value,model:document.getElementById('model-'+p).value});document.getElementById('key-'+p).value='';el.textContent=d.message;setTimeout(()=>location.reload(),700)}catch(e){el.textContent=e.message}}
async function testProvider(p){const el=document.getElementById('result-'+p);el.textContent='Test en cours…';try{const d=await api({action:'test',provider:p});el.textContent=d.message;el.style.color=d.success?'#087f5b':'#b45309'}catch(e){el.textContent=e.message;el.style.color='#b45309'}}
async function saveDefault(){const el=document.getElementById('result-default');el.textContent='Enregistrement…';try{const d=await api({action:'default',provider:document.getElementById('active-provider').value});el.textContent=d.message}catch(e){el.textContent=e.message}}
</script></body></html>